import { test, after } from "node:test";
import fs from "node:fs"; import path from "node:path";
import { execFileSync } from "node:child_process";
import { exportAuditBundle } from "../src/audit_export.js";
import { computeCandidateIdentitySync } from "../src/core/candidate.js";
import { savedSubject, cleanTemp, bundleTexts } from "./helpers/audit_fixture.js";
after(cleanTemp);
const g = (cwd: string, ...a: string[]) => execFileSync("git", a, { cwd, stdio: "pipe", env: { ...process.env, GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1" } });
function run(name: string, prep: (ws: string) => void) {
  test(name, () => {
    const s = savedSubject({ flight: false }); const ws = s.workspace;
    g(ws, "init", "-q", "-b", "main"); g(ws, "config", "user.email", "a@b"); g(ws, "config", "user.name", "n");
    prep(ws); g(ws, "add", "-A"); g(ws, "commit", "-qm", "i");
    const id = computeCandidateIdentitySync(ws).candidateId;
    const st = path.join(s.storeDir, `${s.id}.json`); const j = JSON.parse(fs.readFileSync(st, "utf8")); j.validationReceipts[0].candidateId = id; fs.writeFileSync(st, JSON.stringify(j));
    const get = (o: string) => JSON.parse(bundleTexts((exportAuditBundle(s.request({ out: path.join(s.root, "out", o) })) as any).written.dir)["receipts/candidate-binding.json"]).status;
    const a = get("a");
    fs.appendFileSync(path.join(ws, "a.txt"), "edit\n");
    const b = get("b");
    console.log(`RESULT ${name}: before_edit=${a} after_edit=${b}`);
  });
}
run("plain", (ws) => fs.writeFileSync(path.join(ws, "a.txt"), "hello\n"));
run("text=auto-crlf", (ws) => { fs.writeFileSync(path.join(ws, ".gitattributes"), "* text=auto\n"); fs.writeFileSync(path.join(ws, "a.txt"), "hello\r\nworld\r\n"); });
run("real-filter", (ws) => { fs.writeFileSync(path.join(ws, ".gitattributes"), "* filter=up\n"); fs.appendFileSync(path.join(ws, ".git/config"), `[filter "up"]\n\tclean = tr a-z A-Z\n\tsmudge = cat\n`); fs.writeFileSync(path.join(ws, "a.txt"), "hello\n"); });
EOF
HOME=$(mktemp -d) timeout 300 node --import tsx --test test/zz_probe2.test.ts 2>&1 | grep -E "RESULT|ℹ (pass|fail)|rror" | head

